package com.treasury.payouts.consumer;

import com.treasury.payouts.entity.MerchantAccount;
import com.treasury.payouts.event.PayoutRequestMessage;
import com.treasury.payouts.repository.MerchantAccountRepository;
import com.treasury.payouts.service.DisbursementService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.messaging.handler.annotation.Header;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Component;

@Component
public class PayoutEventConsumer {

    private static final Logger log = LoggerFactory.getLogger(PayoutEventConsumer.class);
    private final MerchantAccountRepository merchantRepository;
    private final DisbursementService disbursementService;

    public PayoutEventConsumer(MerchantAccountRepository merchantRepository, DisbursementService disbursementService) {
        this.merchantRepository = merchantRepository;
        this.disbursementService = disbursementService;
    }

    @KafkaListener(topics = "merchant-payout-requests", groupId = "treasury-payout-workers")
    public void processPayoutEvent(
            @Payload PayoutRequestMessage event,
            @Header(name = "X-Origin-Tenant-Id", required = true) String originTenantId) {
        MerchantAccount account = merchantRepository.findById(event.getMerchantId())
                .orElseThrow(() -> new IllegalArgumentException("Merchant account not found"));
        if (!account.getTenantId().equals(originTenantId)) {
            log.error("Security Alert: Tenant {} attempted unauthorized disbursement from merchant account {}", originTenantId, event.getMerchantId());
            throw new AccessDeniedException("Event origin tenant does not own the target merchant account");
        }
        disbursementService.executeAchWire(account, event.getPayoutAmount(), event.getDestinationIban());
    }
}
